CREATE TABLE IF NOT EXISTS research_canonical_period_facts (fact_id TEXT PRIMARY KEY, isin TEXT NOT NULL, symbol TEXT NOT NULL, scope TEXT NOT NULL, metric TEXT NOT NULL, period_type TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, value_cr REAL, unit TEXT NOT NULL, source_tier TEXT NOT NULL, source TEXT NOT NULL, source_ref TEXT, available_at TEXT NOT NULL, vintage INTEGER NOT NULL DEFAULT 1, supersedes_id TEXT, derivation_json TEXT, quality_flags TEXT DEFAULT '[]', quarantined INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(isin,scope,metric,period_type,period_start,period_end,vintage));
CREATE INDEX IF NOT EXISTS idx_rcpf_lookup ON research_canonical_period_facts(isin,metric,scope,period_type,period_end DESC);
CREATE INDEX IF NOT EXISTS idx_rcpf_symbol ON research_canonical_period_facts(symbol,metric,period_end DESC);
CREATE TABLE IF NOT EXISTS research_metric_definitions (metric TEXT PRIMARY KEY, definition TEXT NOT NULL, unit TEXT NOT NULL, period_basis TEXT NOT NULL, provider_mappings_json TEXT DEFAULT '{}', aliases_json TEXT DEFAULT '[]');
CREATE TABLE IF NOT EXISTS research_trendlyne_catalogue (token TEXT PRIMARY KEY, label TEXT, category TEXT, unit TEXT, money_in_crore INTEGER DEFAULT 0, period_type TEXT, mapped_metric TEXT, tier TEXT, discovered_at TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS research_trendlyne_call_log (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT, purpose TEXT, endpoint TEXT, symbols_json TEXT, tokens_json TEXT, request_hash TEXT NOT NULL, status TEXT NOT NULL, error_code TEXT, error_message TEXT, weighted_cost REAL, response_ref TEXT, called_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS research_items (item_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, tier TEXT NOT NULL, url TEXT NOT NULL, title TEXT, publisher TEXT, published_at TEXT, retrieved_at TEXT NOT NULL, excerpt TEXT NOT NULL, sub_question_ids_json TEXT DEFAULT '[]', status TEXT NOT NULL, traced_to TEXT, url_hash TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS research_conflicts (id INTEGER PRIMARY KEY AUTOINCREMENT, isin TEXT, metric TEXT, period_end TEXT, scope TEXT, fact_a TEXT, fact_b TEXT, value_a REAL, value_b REAL, rel_diff REAL, status TEXT DEFAULT 'OPEN', note TEXT, detected_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS research_report_runs (run_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, as_of TEXT NOT NULL, routine_version TEXT NOT NULL, contract_version TEXT NOT NULL, bundle_hash TEXT NOT NULL, drafter_provider TEXT, drafter_model TEXT, reviewer_provider TEXT, reviewer_model TEXT, status TEXT NOT NULL, validator_verdict_json TEXT, gate_verdict_json TEXT, spend_usd REAL, loops INTEGER DEFAULT 0, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS research_answer_store (run_id TEXT NOT NULL, sub_question_id TEXT NOT NULL, state TEXT NOT NULL, claims_json TEXT NOT NULL, narrative TEXT, gap TEXT, next_action TEXT, sources_searched_json TEXT, premise_check_json TEXT, review_status TEXT, PRIMARY KEY(run_id,sub_question_id));
CREATE TABLE IF NOT EXISTS research_review_findings (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, sub_question_id TEXT, severity TEXT, defect TEXT, evidence TEXT, required_fix TEXT, resolution TEXT, loop_no INTEGER);
CREATE TABLE IF NOT EXISTS research_filter_scorecard (run_id TEXT NOT NULL, symbol TEXT NOT NULL, as_of TEXT NOT NULL, filter_id INTEGER NOT NULL, label TEXT, observed REAL, unit TEXT, threshold REAL, comparator TEXT, gap REAL, status TEXT NOT NULL, basis TEXT, period TEXT, scope TEXT, sources_json TEXT, formula TEXT, note TEXT, reason_unverifiable TEXT, PRIMARY KEY(run_id,symbol,filter_id));
